import {
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

export const generatedHeader =
  "// Generated by scripts/generate-openstory-stories.mjs. Do not edit by hand.";

const examplesDir = "registry/default/examples";
const generatedDir = "src/openstory/generated";
const itemsPath = "registry/default/items.json";

const variantSuffixes = [
  "controlled-multiple-triggers",
  "close-confirmation",
  "detached-triggers",
  "multiple-triggers",
  "month-year-selector",
  "date-time-picker",
  "custom-cell-size",
  "custom-colors",
  "nested-parent",
  "native-button",
  "open-from-menu",
  "row-actions",
  "small-media",
  "week-numbers",
  "date-of-birth",
  "radio-group",
  "button-group",
  "destructive",
  "alphanumeric",
  "checkboxes",
  "controlled",
  "scrollable",
  "separator",
  "shortcuts",
  "secondary",
  "animated",
  "disabled",
  "dropdown",
  "fallback",
  "multiple",
  "outlined",
  "portrait",
  "rounded",
  "skeleton",
  "spacing",
  "spinner",
  "submenu",
  "success",
  "warning",
  "as-child",
  "complex",
  "default",
  "groups",
  "hidden",
  "invalid",
  "labeling",
  "loading",
  "outline",
  "pattern",
  "primary",
  "sizing",
  "square",
  "vertical",
  "with-icon",
  "action",
  "badge",
  "basic",
  "booked",
  "error",
  "ghost",
  "icons",
  "large",
  "media",
  "parent",
  "range",
  "right",
  "sizes",
  "small",
  "solid",
  "form",
  "icon",
  "link",
  "rtl",
  "size",
  "text",
  "grid",
  "axis",
  "card",
];

const readJsonFile = (filePath) => JSON.parse(readFileSync(filePath, "utf-8"));

const titleCaseWord = (word) => {
  const upper = word.toUpperCase();

  if (["API", "OTP", "RTL", "UI", "URL"].includes(upper)) {
    return upper;
  }

  return `${word.slice(0, 1).toUpperCase()}${word.slice(1).toLowerCase()}`;
};

const splitWords = (value) =>
  value
    .replace(/^shadcn-/u, "")
    .replace(/^base-ui-/u, "")
    .replace(/([A-Z]+)([A-Z][a-z])/gu, "$1 $2")
    .replace(/([a-z0-9])([A-Z])/gu, "$1 $2")
    .replace(/[/_-]+/gu, " ")
    .trim()
    .split(/\s+/u)
    .filter(Boolean);

export const humanize = (value) => splitWords(value).map(titleCaseWord).join(" ");

export const slugify = (value) =>
  splitWords(value)
    .map((word) => word.toLowerCase())
    .join("-");

export const pascalCase = (value) => {
  const identifier = splitWords(value)
    .map((word) => titleCaseWord(word).replace(/[^A-Za-z0-9]/gu, ""))
    .join("");

  if (/^[0-9]/u.test(identifier)) {
    return `Story${identifier}`;
  }

  return identifier || "Story";
};

const line = (value = "") => `${value}\n`;

const removeLanePrefix = (slug) => {
  if (slug.startsWith("shadcn-")) {
    return slug.slice("shadcn-".length);
  }

  if (slug.startsWith("base-ui-")) {
    return slug.slice("base-ui-".length);
  }

  return slug;
};

const laneForSlug = (slug) => {
  if (slug.startsWith("shadcn-")) {
    return "shadcn";
  }

  if (slug.startsWith("base-ui-")) {
    return "base-ui";
  }

  return "registry";
};

const splitSlug = (slug) => {
  const withoutLane = removeLanePrefix(slug);
  const variant = variantSuffixes.find((suffix) =>
    withoutLane.endsWith(`-${suffix}`)
  );

  if (variant !== undefined) {
    return {
      componentSlug: withoutLane.slice(0, -(variant.length + 1)),
      variantSlug: variant,
    };
  }

  const parts = withoutLane.split("-");

  return {
    componentSlug: parts.slice(0, -1).join("-") || withoutLane,
    variantSlug: parts.at(-1) ?? "basic",
  };
};

const componentNameFromItem = (item, slug) => {
  const component = item?.meta?.foldkit?.component;

  if (typeof component === "string" && component.trim() !== "") {
    return humanize(component);
  }

  return humanize(splitSlug(slug).componentSlug);
};

const titlePrefixPattern = (lane) => {
  if (lane === "base-ui") {
    return /^(base ui|base-ui)\s+/iu;
  }

  if (lane === "shadcn") {
    return /^shadcn\s+/iu;
  }

  return /^registry\s+/iu;
};

const storyNameFromItemTitle = ({ item, lane, componentName }) => {
  if (typeof item?.title !== "string") {
    return undefined;
  }

  const withoutLane = item.title.replace(titlePrefixPattern(lane), "");
  const componentPattern = new RegExp(
    `^${componentName.replace(/[.*+?^${}()|[\]\\]/gu, "\\$&")}\\s+`,
    "iu"
  );
  const storyName = withoutLane.replace(componentPattern, "").trim();

  if (storyName === "" || storyName === withoutLane) {
    return undefined;
  }

  return storyName;
};

const storyNameFromItemExample = (item) => {
  const example = item?.meta?.foldkit?.example;

  if (typeof example !== "string" || example.trim() === "") {
    return undefined;
  }

  return humanize(example.replace(/^shadcn-/u, "").replace(/^base-ui-/u, ""));
};

const storyNameForSlug = ({ slug, item, lane, componentName }) =>
  storyNameFromItemTitle({ item, lane, componentName }) ??
  storyNameFromItemExample(item) ??
  humanize(splitSlug(slug).variantSlug);

export const discoverExamples = (rootDir = process.cwd()) => {
  const absoluteExamplesDir = path.join(rootDir, examplesDir);

  return readdirSync(absoluteExamplesDir, { withFileTypes: true })
    .filter((entry) => entry.isDirectory())
    .map((entry) => entry.name)
    .filter((slug) => existsSync(path.join(absoluteExamplesDir, slug, "main.ts")))
    .sort((left, right) => left.localeCompare(right));
};

export const readRegistryItems = (rootDir = process.cwd()) => {
  const absoluteItemsPath = path.join(rootDir, itemsPath);

  if (!existsSync(absoluteItemsPath)) {
    return [];
  }

  return readJsonFile(absoluteItemsPath);
};

export const createCatalog = ({ exampleSlugs, registryItems }) => {
  const itemsByName = new Map(registryItems.map((item) => [item.name, item]));
  const groupsByTitle = new Map();

  for (const slug of [...exampleSlugs].sort((left, right) => left.localeCompare(right))) {
    const item = itemsByName.get(slug);
    const lane = laneForSlug(slug);
    const componentName = componentNameFromItem(item, slug);
    const title = `${lane}/${componentName}`;
    const storyName = storyNameForSlug({ slug, item, lane, componentName });
    const group =
      groupsByTitle.get(title) ??
      {
        title,
        stories: [],
      };

    group.stories.push({
      exportName: pascalCase(storyName),
      importName: `${pascalCase(slug)}Example`,
      modulePath: `../../../${examplesDir}/${slug}/main`,
      name: storyName,
      slug,
    });
    groupsByTitle.set(title, group);
  }

  return [...groupsByTitle.values()]
    .map((group) => disambiguateGroupStories(group))
    .sort((left, right) => left.title.localeCompare(right.title));
};

const disambiguateGroupStories = (group) => {
  const seenExports = new Map();
  const seenNames = new Map();

  return {
    ...group,
    stories: group.stories.map((story) => {
      const exportCount = (seenExports.get(story.exportName) ?? 0) + 1;
      const nameCount = (seenNames.get(story.name) ?? 0) + 1;
      seenExports.set(story.exportName, exportCount);
      seenNames.set(story.name, nameCount);

      if (exportCount === 1 && nameCount === 1) {
        return story;
      }

      const suffix = Math.max(exportCount, nameCount);

      return {
        ...story,
        exportName: `${story.exportName}${suffix}`,
        name: `${story.name} ${suffix}`,
      };
    }),
  };
};

const storyFileName = (title) => `${slugify(title)}.stories.ts`;

const renderStory = (story) =>
  [
    line(`export const ${story.exportName}: Story = {`),
    line(`  name: ${JSON.stringify(story.name)},`),
    line(`  render: () => ${story.importName},`),
    line("}"),
  ].join("");

const renderGroup = (group) =>
  [
    line(generatedHeader),
    line('import type { Meta, StoryObj } from "openstory/foldkit"'),
    line(),
    ...group.stories.map((story) =>
      line(`import * as ${story.importName} from "${story.modulePath}"`)
    ),
    line(),
    line("const meta = {"),
    line(`  title: ${JSON.stringify(group.title)},`),
    line("} satisfies Meta"),
    line(),
    line("export default meta"),
    line(),
    line("type Story = StoryObj<typeof meta>"),
    line(),
    group.stories.map(renderStory).join("\n"),
  ].join("");

export const renderGeneratedFiles = (catalog) =>
  new Map(
    catalog.map((group) => [
      path.join(generatedDir, storyFileName(group.title)),
      renderGroup(group),
    ])
  );

export const storyId = ({ title, name }) =>
  `${slugify(title)}--${slugify(name)}`;

export const generateOpenstoryStories = (rootDir = process.cwd()) => {
  const exampleSlugs = discoverExamples(rootDir);
  const registryItems = readRegistryItems(rootDir);
  const catalog = createCatalog({ exampleSlugs, registryItems });

  return {
    catalog,
    files: renderGeneratedFiles(catalog),
  };
};

export const writeGeneratedFiles = ({ rootDir = process.cwd(), files }) => {
  const absoluteGeneratedDir = path.join(rootDir, generatedDir);
  rmSync(absoluteGeneratedDir, { recursive: true, force: true });
  mkdirSync(absoluteGeneratedDir, { recursive: true });

  for (const [relativeFilePath, source] of files) {
    writeFileSync(path.join(rootDir, relativeFilePath), source, "utf-8");
  }
};

export const checkGeneratedFiles = ({ rootDir = process.cwd(), files }) => {
  const failures = [];
  const generatedStoryDir = path.join(rootDir, generatedDir);
  const expectedPaths = new Set([...files.keys()]);

  if (existsSync(generatedStoryDir)) {
    for (const entry of readdirSync(generatedStoryDir)) {
      const relativePath = path.join(generatedDir, entry);

      if (entry.endsWith(".stories.ts") && !expectedPaths.has(relativePath)) {
        failures.push(`${relativePath}: stale generated story file`);
      }
    }
  }

  for (const [relativeFilePath, expectedSource] of files) {
    const absoluteFilePath = path.join(rootDir, relativeFilePath);

    if (!existsSync(absoluteFilePath)) {
      failures.push(`${relativeFilePath}: missing generated story file`);
      continue;
    }

    const actualSource = readFileSync(absoluteFilePath, "utf-8");

    if (actualSource !== expectedSource) {
      failures.push(`${relativeFilePath}: generated story file is stale`);
    }
  }

  return failures;
};

const currentFilePath = fileURLToPath(import.meta.url);

if (process.argv[1] === currentFilePath) {
  const generated = generateOpenstoryStories();

  if (process.argv.includes("--check")) {
    const failures = checkGeneratedFiles(generated);

    if (failures.length > 0) {
      console.error("Generated Openstory registry stories are stale:");
      for (const failure of failures) {
        console.error(`- ${failure}`);
      }
      process.exit(1);
    }

    const storyCount = generated.catalog.reduce(
      (count, group) => count + group.stories.length,
      0
    );
    console.log(`Checked ${storyCount} generated Openstory registry stories`);
  } else {
    writeGeneratedFiles(generated);
    const storyCount = generated.catalog.reduce(
      (count, group) => count + group.stories.length,
      0
    );
    console.log(`Generated ${storyCount} Openstory registry stories`);
  }
}
